/* V3: khóa cuộn toàn bộ trang; mỗi mục navbar là một màn hình độc lập. */
html,body{width:100%;height:100%;max-height:100%;overflow:hidden!important;overscroll-behavior:none;}
body{position:relative;touch-action:auto;}
.hero{position:fixed;inset:0;width:100%;height:100vh;height:100dvh;min-height:0!important;overflow:hidden;}
.nav{position:fixed!important;inset:0 0 auto 0;width:100%;z-index:50;}
.footerhint{display:none!important;}
.menu-toggle{display:none;background:rgba(255,255,255,.68);color:#193e77;border:1px solid rgba(36,82,146,.2);border-radius:12px;width:42px;height:42px;align-items:center;justify-content:center;font-size:23px;cursor:pointer;}
.next{position:fixed;inset:0;z-index:20;display:flex;align-items:center;justify-content:center;overflow:hidden;padding:100px 28px 32px;text-align:left;background:linear-gradient(135deg,rgba(239,247,255,.96),rgba(219,234,252,.94));backdrop-filter:blur(18px);opacity:0;visibility:hidden;pointer-events:none;transform:translateY(14px);transition:opacity .32s ease,visibility .32s ease,transform .32s ease;}
.next.is-active{opacity:1;visibility:visible;pointer-events:auto;transform:translateY(0);}
.page-content{position:relative;z-index:1;width:min(1100px,100%);max-height:100%;overflow:auto;overscroll-behavior:contain;padding:12px 6px 24px;scrollbar-width:thin;}
.page-kicker{font-size:12px;letter-spacing:4px;font-weight:700;color:#4176c5;margin:0 0 16px;}
.next h2{font:600 clamp(40px,5.6vw,76px)/1.07 'Playfair Display',serif;letter-spacing:-2px;color:#163b74;margin:0 0 16px;}
.page-description{font-size:clamp(14px,1.5vw,18px);line-height:1.65;color:#49698d;max-width:640px;margin:0 0 30px;}
.look-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;}
.look-tile{min-height:210px;border-radius:23px;padding:24px;display:flex;flex-direction:column;justify-content:space-between;border:1px solid rgba(255,255,255,.92);background:linear-gradient(145deg,rgba(255,255,255,.72),rgba(214,229,249,.64));box-shadow:0 14px 35px rgba(43,89,156,.10);position:relative;overflow:hidden;}
.look-tile:before{content:'';position:absolute;right:-35px;top:-55px;width:190px;height:190px;border-radius:50%;background:radial-gradient(circle,rgba(101,155,231,.23),transparent 70%);pointer-events:none;}
.look-number{font-size:12px;letter-spacing:3px;color:#6487b5;font-weight:700;}
.look-tile h3{font:600 clamp(20px,2vw,28px) 'Playfair Display',serif;margin:0 0 8px;color:#193b6d;}
.look-tile p{font-size:13px;line-height:1.55;color:#547090;margin:0;}
.page-note{font-size:12px;color:#7b91ac;margin-top:24px;}
.page-ambient{position:absolute;border-radius:50%;filter:blur(2px);pointer-events:none;}
.page-ambient-one{width:430px;height:430px;right:-120px;top:0;background:radial-gradient(circle,rgba(141,185,250,.32),transparent 68%);}
.page-ambient-two{width:390px;height:390px;left:-180px;bottom:-170px;background:radial-gradient(circle,rgba(174,207,250,.40),transparent 70%);}
.look-dialog-backdrop{position:fixed;inset:0;z-index:70;display:grid;place-items:center;padding:24px;background:rgba(11,31,61,.38);backdrop-filter:blur(8px);}
.look-dialog-backdrop[hidden]{display:none;}
.look-dialog{width:min(450px,100%);position:relative;padding:38px 32px;background:rgba(250,253,255,.96);border:1px solid white;border-radius:24px;box-shadow:0 30px 90px rgba(0,30,72,.22);}
.look-dialog h2{font:600 39px 'Playfair Display',serif;color:#163a73;margin:12px 0;}
.look-dialog p{font-size:15px;line-height:1.7;color:#476486;}
.dialog-kicker{font-size:11px;font-weight:700;letter-spacing:3px;color:#4274ba;}
.look-dialog .dialog-note{font-size:12px;color:#6b84a5;}
.dialog-close{position:absolute;right:15px;top:12px;border:0;background:transparent;color:#34557c;font-size:32px;cursor:pointer;}
@media(max-width:1000px){.hero .copy{top:48%;}}
@media(max-width:680px){
  .nav{height:65px;padding:0 18px;}
  .menu-toggle{display:flex;}
  .nav .links{display:none;position:absolute;top:72px;left:16px;right:16px;flex-direction:column;gap:0;padding:10px;background:rgba(248,251,255,.96);border:1px solid rgba(255,255,255,.95);border-radius:18px;box-shadow:0 18px 50px rgba(14,54,112,.18);backdrop-filter:blur(20px);}
  .nav .links.is-open{display:flex;}
  .nav .links a{padding:13px 16px;border-radius:12px;font-size:15px;}
  .nav .links a.active{background:rgba(201,225,255,.45);}
  .hero .copy{top:95px;}
  .hero .model{height:min(52dvh,490px);}
  .next{padding:100px 20px 16px;}
  .page-content{max-height:100%;padding:0 0 16px;}
  .next h2{font-size:clamp(35px,10vw,50px);}
  .page-description{font-size:14px;margin-bottom:20px;}
  .look-grid{grid-template-columns:1fr;gap:12px;}
  .look-tile{min-height:130px;padding:18px;}
  .page-kicker{font-size:10px;letter-spacing:2px;}
}
@media(max-height:740px) and (max-width:680px){.hero .copy{top:82px}.hero .copy h1{font-size:43px}.hero .model{height:49dvh}}
@media(max-height:650px) and (min-width:681px){.hero .model{height:85vh;max-height:calc(100% - 60px)}.hero .copy{transform:translateY(-30%)}.look-tile{min-height:155px}.next{padding-top:80px}.page-description{margin-bottom:14px}}
@media(prefers-reduced-motion:reduce){.next{transition:none}}

/* Dz-Fashion V4: chuyển màn hình trượt ngang, không cuộn trang. */
.dz-stage{position:fixed;inset:0;z-index:0;width:100%;height:100vh;height:100dvh;overflow:hidden;isolation:isolate;background:#e9f2ff;}
.dz-stage>.dz-screen{position:absolute!important;inset:0!important;width:100%!important;height:100%!important;min-height:0!important;margin:0;will-change:transform,opacity;backface-visibility:hidden;transform:translate3d(0,0,0);}
.dz-stage>.next{display:flex!important;visibility:visible!important;opacity:1!important;pointer-events:auto!important;transition:none!important;}
.dz-stage>.dz-screen[aria-hidden="true"]{pointer-events:none!important;}
.dz-stage>.hero{isolation:isolate;}
.dz-stage>.next .page-content{overscroll-behavior:contain;}
@media(prefers-reduced-motion:reduce){.dz-stage>.dz-screen{will-change:auto;}}

/* Staggered cinematic swipe — big objects > small objects > whole screen */
.dz-stage.dz-is-transitioning{pointer-events:none;}
.dz-stage.dz-is-transitioning .dz-screen{overflow:hidden!important;}
.dz-stage.dz-is-transitioning .model,
.dz-stage.dz-is-transitioning .copy h1,
.dz-stage.dz-is-transitioning .orb,
.dz-stage.dz-is-transitioning .right-card,
.dz-stage.dz-is-transitioning .look-tile,
.dz-stage.dz-is-transitioning .page-content h2{will-change:transform,opacity;backface-visibility:hidden;}
.dz-stage>.dz-screen.dz-entering::after{
  content:"";position:absolute;z-index:10;left:0;top:0;bottom:0;width:3px;
  background:linear-gradient(180deg,transparent,rgba(255,255,255,.88) 22%,rgba(119,176,255,.65) 56%,transparent);
  box-shadow:0 0 26px 5px rgba(191,220,255,.24);pointer-events:none;
}
@media(prefers-reduced-motion:reduce){.dz-stage>.dz-screen.dz-entering::after{display:none}}

/* ===== DZ-FASHION / VISUAL SYSTEM V5 ===== */
:root{--ink:#132b4c;--ocean:#275ab1;--electric:#537dd8;--ice:#e4f3ff;--frost:rgba(250,253,255,.72);--nav-height:78px}
html{color-scheme:light}
body{font-family:'DM Sans',Arial,sans-serif;-webkit-font-smoothing:antialiased;background:#edf5ff}
::selection{background:#93bbff;color:#102e64}
button,a{ -webkit-tap-highlight-color:transparent }
button:focus-visible,a:focus-visible,[role=button]:focus-visible{outline:3px solid #4b8ff3;outline-offset:4px}
/* The environmental shot stays sharp; only its overlay is softened. */
.hero{background:#daeafa}
.hero .campus{filter:saturate(.84) contrast(1.045) brightness(1.045);background-position:center 54%}
.hero .wash{background:linear-gradient(90deg,rgba(246,250,255,.76) 0%,rgba(244,249,255,.56) 21%,rgba(246,251,255,.05) 49%,rgba(234,244,255,.09) 76%,rgba(218,235,251,.27) 100%),linear-gradient(0deg,rgba(218,236,255,.58),transparent 26%,transparent 72%,rgba(208,228,250,.19));}
.hero::before{content:'';position:absolute;inset:0;pointer-events:none;z-index:0;background:radial-gradient(ellipse 47% 70% at 53% 55%,rgba(255,255,255,.16),transparent 75%),linear-gradient(to bottom,rgba(14,57,107,.09),transparent 27%);}
.hero::after{content:'';inset:0;position:absolute;z-index:1;pointer-events:none;border:1px solid rgba(255,255,255,.20);box-shadow:inset 0 0 150px rgba(16,65,124,.055);}
.hero-halo{pointer-events:none;position:absolute;z-index:0;width:min(51vw,720px);height:min(70vw,720px);left:50%;top:52%;transform:translate(-50%,-50%);border-radius:50%;background:radial-gradient(ellipse,rgba(255,255,255,.38) 0%,rgba(164,211,255,.14) 40%,transparent 70%);filter:blur(18px)}
.hero-beam{pointer-events:none;z-index:1;position:absolute;top:-15%;left:23%;height:105%;width:26%;transform:rotate(27deg);background:linear-gradient(90deg,transparent,rgba(255,255,255,.14),transparent);opacity:.65}
/* Nav: compact floating glass strip */
.nav{top:14px!important;left:clamp(14px,2.4vw,42px)!important;right:clamp(14px,2.4vw,42px)!important;width:auto!important;inset:14px clamp(14px,2.4vw,42px) auto!important;height:72px;padding:0 clamp(19px,2.9vw,43px);border-radius:21px;background:rgba(255,255,255,.72);border:1px solid rgba(255,255,255,.87);box-shadow:0 12px 52px rgba(20,65,121,.12),inset 0 1px 0 rgba(255,255,255,.8);backdrop-filter:blur(26px) saturate(1.4);-webkit-backdrop-filter:blur(26px) saturate(1.4)}
.nav::before{content:'';position:absolute;inset:1px;border:1px solid rgba(255,255,255,.3);border-radius:20px;pointer-events:none}
.logo{display:inline-flex;align-items:center;gap:12px;font:700 clamp(22px,2.1vw,29px)/1 'Playfair Display',Georgia,serif;letter-spacing:-1.4px;color:#11305e;white-space:nowrap}
.dz-logo-emblem{display:inline-grid;place-items:center;width:38px;height:38px;border-radius:12px;background:linear-gradient(145deg,#113566,#3777c2);color:white;font:500 21px/1 Georgia,serif;box-shadow:0 6px 16px rgba(28,78,153,.25);transform:rotate(-9deg)}
.links{gap:5px;padding:4px;background:rgba(221,235,253,.29);border:1px solid rgba(244,250,255,.5);border-radius:40px;font-size:13px;font-weight:700;white-space:nowrap}
.links a{padding:11px 17px;border-radius:30px;transition:background .28s,color .28s,box-shadow .28s}
.links a:hover{color:#1d5db3;background:rgba(255,255,255,.54)}
.links a.active{background:linear-gradient(130deg,#275eb8,#417aca);color:#fff!important;box-shadow:0 6px 15px rgba(25,74,146,.22)}
.pill{display:inline-flex;align-items:center;gap:9px;background:linear-gradient(135deg,#163b73,#3573c4);border:1px solid rgba(41,80,145,.1);color:white;padding:12px 20px;box-shadow:0 8px 23px rgba(43,89,162,.19);transition:transform .26s,box-shadow .26s}
.pill:hover{transform:translateY(-2px);box-shadow:0 12px 28px rgba(43,89,162,.28)}
/* Hero editorial type */
.copy{left:clamp(35px,6.3vw,112px);top:51%;transform:translateY(-34%);max-width:min(35vw,510px);}
.eyebrow{font-size:11px;letter-spacing:3.6px;display:inline-flex;align-items:center;gap:11px;background:rgba(255,255,255,.54);border:1px solid rgba(255,255,255,.8);padding:9px 13px;border-radius:40px;box-shadow:0 5px 20px rgba(28,73,133,.07);color:#2d5e9d;margin-bottom:22px}
.eyebrow::before{content:'';display:block;height:7px;width:7px;border-radius:50%;background:#3b80d0;box-shadow:0 0 0 4px rgba(56,125,213,.12)}
.copy h1{font-size:clamp(57px,6.3vw,106px);font-weight:600;line-height:.96;letter-spacing:-4.8px;color:#142d55;text-shadow:0 2px 22px rgba(255,255,255,.56)}
.copy h1 em{color:#2f68b9;font-style:italic;background:linear-gradient(112deg,#174d96 20%,#478aca 68%,#1f539e);background-clip:text;-webkit-background-clip:text;-webkit-text-fill-color:transparent}
.copy .desc{font-size:clamp(14px,1.13vw,17px);font-weight:500;line-height:1.85;color:#30537a;max-width:345px;margin:26px 0 24px;text-shadow:0 1px 8px rgba(255,255,255,.5)}
.cta{font-size:14px;letter-spacing:.1px;gap:18px;background:linear-gradient(130deg,#1a4c9c,#3e80d0);border:1px solid rgba(255,255,255,.65);padding:15px 22px 15px 24px;box-shadow:0 13px 35px rgba(23,76,153,.28),inset 0 1px 0 rgba(255,255,255,.3);transition:transform .3s,box-shadow .3s,background .3s}
.cta span{display:grid;place-items:center;width:30px;height:30px;border-radius:50%;background:rgba(255,255,255,.16);font-size:19px;transition:transform .3s}
.cta:hover{transform:translateY(-4px);box-shadow:0 18px 42px rgba(23,76,153,.32)}
.cta:hover span{transform:translate(3px,-3px)}
.hero-chapter{margin-top:28px;display:flex;align-items:center;gap:14px;color:#2c4b71;font-size:11px;letter-spacing:1px;font-weight:700}
.hero-chapter b{display:block;width:47px;height:1px;background:linear-gradient(90deg,#2c6eb7,transparent)}
.hero-chapter span{opacity:.8}
/* Model: clean, sharp foreground cutout with cinematic spotlight */
.model-wrap{z-index:3;align-items:flex-end;filter:none}
.model-wrap::before{content:'';position:absolute;z-index:-1;width:480px;height:83%;bottom:5%;left:50%;transform:translateX(-50%);background:radial-gradient(ellipse at 50% 48%,rgba(241,249,255,.40),rgba(137,197,255,.12) 38%,transparent 67%);filter:blur(9px)}
