.hero .model{height:min(90vh,920px);filter:drop-shadow(9px 14px 11px rgba(12,33,61,.20));image-rendering:auto}
.orb{z-index:2;top:55%;width:min(29vw,415px);height:min(65vh,610px);border:1px solid rgba(243,251,255,.57);box-shadow:0 0 29px rgba(234,249,255,.4),inset 0 0 35px rgba(241,250,255,.12);opacity:.8}
.orb::before,.orb::after{content:'';position:absolute;border-radius:50%;inset:20px -15px;border:1px solid rgba(255,255,255,.24);transform:rotate(27deg)}
.orb::after{inset:4px 35px;border-color:rgba(121,186,247,.43);transform:rotate(-35deg)}
/* Featured capsule */
