/* Scroll-snap kiểu cinematic: màn hình XU HƯỚNG chồng lên Trang chủ, KHÔNG cuộn toàn trang. */
html,body{overscroll-behavior:none!important; overflow:hidden!important;}
.dz-stage>.dz-screen{contain:layout style;}
.dz-stage>.dz-screen[data-screen="xuhuong"]{
 background:linear-gradient(139deg,#f7fbff 0%,#edf5fe 55%,#e5f0fa 100%)!important;
}
/* Xu hướng tràn khỏi viewport trên thiết bị nhỏ: chỉ cuộn trong khu nội dung quảng cáo. */
.dz-stage>.dz-screen[data-screen="xuhuong"] .page-content{
 scrollbar-width:thin;scroll-behavior:smooth;overscroll-behavior:contain;
}
.dz-stage>.dz-screen[data-screen="xuhuong"] .page-content::-webkit-scrollbar{width:5px;}
.dz-stage>.dz-screen[data-screen="xuhuong"] .page-content::-webkit-scrollbar-thumb{background:#a9bdd5;border-radius:8px;}
/* Vệt sáng theo cạnh trên: tăng cảm giác màn hình đang được kéo từ phía dưới lên. */
.dz-stage>.dz-screen.dz-vertical-entering::after{
 content:"";position:absolute;z-index:12;top:0;left:0;right:0;height:2px;
 background:linear-gradient(90deg,transparent 8%,rgba(255,255,255,.9) 38%,rgba(119,171,230,.76) 65%,transparent 92%);
 box-shadow:0 0 23px 6px rgba(129,187,242,.19);pointer-events:none;
}
/* Giữ lời mời tương tác cực gọn, không dùng thanh cuộn hay thanh điều khiển. */
.dz-scroll-cue{position:absolute;bottom:25px;right:30px;z-index:25;display:flex;align-items:center;gap:10px;
 color:#f4faff;letter-spacing:.18em;text-transform:uppercase;font-size:10px;font-weight:750;
 background:none;border:0;cursor:pointer;text-shadow:0 2px 12px #0d274990;
 opacity:.78;transition:opacity .28s ease,transform .28s ease;}
.dz-scroll-cue:hover,.dz-scroll-cue:focus-visible{opacity:1;transform:translateY(3px)}
.dz-scroll-cue svg{width:20px;height:20px;stroke:currentColor;stroke-width:1.8;fill:none}
.dz-stage.dz-is-transitioning .dz-scroll-cue{pointer-events:none}
@media(max-width:680px){.dz-scroll-cue{bottom:18px;right:18px;font-size:9px;gap:7px;}}
@media(prefers-reduced-motion:reduce){.dz-scroll-cue{transition:none}.dz-stage>.dz-screen.dz-vertical-entering::after{display:none}}
